"""S mechanism: backtracking search (depth-first, chronological).

Owns: the trail (a plain list of undo callables) and undo().
Variables: none of its own; a node is whatever the caller says it is.

search(root, children, is_solution, trail=None, stack=None) is a generator.
The tree is given by two functions of the caller:
  is_solution(node) -- true if node is a solution: it is yielded, not expanded;
  children(node)    -- an iterable of node's children, tried in its order
                       (it may be a generator, and is advanced lazily).
Nodes are visited depth first, leftmost child first, root included; after a
subtree is finished, the search returns to the most recent choice point that
has an untried child (chronological backtracking). Solutions are yielded one
at a time, in that order, so a caller takes one (next) or many (a loop); the
search does nothing until asked for the next solution.

Trail. A caller that changes shared state to make a child (binding a
variable, narrowing a domain) appends a zero-argument callable to `trail`
that undoes the change. Before each child of a node is produced, the trail is
undone back to its length when that node was reached, so every child starts
from its parent's state. When the search is exhausted, the trail is undone to
its length at the start. A caller that stops early keeps the state of the
last solution; undo(trail, mark) restores an earlier state.

The search is iterative: its depth is limited by memory, not by the
recursion limit. `stack`, if given, is the list used for the pending choice
points (one entry per open node: its iterator of untried children and its
trail mark), so that a caller can register it as its pending structure.
"""


def undo(trail, mark):
    """Undo the trail's entries after its first `mark`, last first."""
    while len(trail) > mark:
        trail.pop()()


def search(root, children, is_solution, trail=None, stack=None):
    trail = [] if trail is None else trail
    stack = [] if stack is None else stack
    stack.append((iter((root,)), len(trail)))
    while stack:
        alternatives, mark = stack[-1]
        undo(trail, mark)
        node = next(alternatives, stack)  # the stack itself marks "no more"
        if node is stack:
            stack.pop()
        elif is_solution(node):
            yield node
        else:
            stack.append((iter(children(node)), len(trail)))
"""S mechanism: logic variables and a suspension queue.

Owns: Var, deref() (the variables of the S mechanisms; propagate.py accepts
them as its variables, search.py has none). Uses search.py's trail
convention (a list of undo callables) when a trail is given.

A Var is unbound until it is bound once. Binding a Var to another unbound Var
makes them one variable; binding to anything else gives it that value.
deref(t) follows bindings to an unbound Var or a value. Values are compared
with ==; terms are not unified inside (a value that contains Vars is just a
value).

Queue holds goals (zero-argument callables) waiting on unknowns:
  wait(goal, *vars) -- goal is held until any one of vars is bound to a value
                       (if one already is, or none is given, it is ready now);
                       a goal waiting on several vars is woken once;
  bind(v, x, trail) -- bind v to x and wake the goals waiting on v; True if
                       consistent, False if both are values and differ
                       (nothing is changed then);
  run()             -- run ready goals until none is ready; returns how many ran.
Order (fairness): ready goals run first in, first out. A binding appends the
goals it wakes at the back of the ready queue, in the order they suspended.
So a goal, once woken, runs after every goal ready before it and before every
goal woken after it: none waits for ever while each goal returns. A goal may
wait again (to wait for all of several variables, wait on the next unbound
one) and may bind, which wakes others behind it. Binding two unbound Vars
together wakes nothing: the goals of the first wait on the merged variable.

`held` (key -> goal; keys increase in suspension order) is the suspended goals, `ready` the
goals woken and not yet run; a caller may register either. With a trail, a
binding is undone by search.undo: the variable is unbound again and the goals
it woke are held again. Undo only with the ready queue empty (call run()
first): a goal that has run is not un-run, though its trailed bindings are
undone.
"""


class Var:
    __slots__ = ("ref", "waiting", "name")

    def __init__(self, name="_"):
        self.ref = self     # itself while unbound
        self.waiting = []   # keys of goals in Queue.held
        self.name = name

    def __repr__(self):
        t = deref(self)
        return t.name if isinstance(t, Var) else repr(t)


def deref(t):
    while isinstance(t, Var) and t.ref is not t:
        t = t.ref
    return t


class Queue:
    def __init__(self):
        self.held = {}
        self.ready = []
        self.key = 0

    def wait(self, goal, *vars):
        vs = [deref(v) for v in vars]
        if not vs or not all(isinstance(v, Var) for v in vs):
            self.ready.append(goal)
            return
        self.key += 1
        self.held[self.key] = goal
        for v in vs:
            v.waiting.append(self.key)

    def bind(self, v, x, trail=None):
        a, b = deref(v), deref(x)
        if a is b:
            return True
        if not isinstance(a, Var):
            a, b = b, a
        if not isinstance(a, Var):
            return a == b
        a.ref = b
        if isinstance(b, Var):
            n = len(b.waiting)
            b.waiting += a.waiting

            def back():
                a.ref = a
                del b.waiting[n:]
        else:
            woken = [(k, self.held.pop(k)) for k in a.waiting if k in self.held]
            self.ready += [g for _, g in woken]

            def back():
                a.ref = a
                self.held.update(woken)
        if trail is not None:
            trail.append(back)
        return True

    def run(self):
        n = 0
        try:
            while n < len(self.ready):
                n += 1
                self.ready[n - 1]()
        finally:
            del self.ready[:n]
        return n
"""S mechanism: a constraint propagator over finite integer domains, with
exact linear relations.

Variables: any hashable key, for instance a name or a suspend.Var (which
owns the variables of the S mechanisms; this module defines none). Uses
search.py for labelling and its trail convention for undoing.

Store(trail=None) holds a domain (a set of integers) per variable and the
constraints posted on them:
  var(v, values)           -- declare v with domain `values` (any iterable);
  linear(terms, op, c)     -- post sum(a * v for a, v in terms) op c, with op
                              '==', '<=' or '>=' and integer a, c (exact: ints);
  relation(vars, pred)     -- post pred(*values) over vars, any arity;
  fix(v=None, keep=None)   -- optionally narrow v to the values satisfying keep,
                              then propagate to a fixpoint; False on failure;
  value(v)                 -- v's value if its domain is one value, else None;
  residual()               -- the constraints not yet decided: those with a
                              variable whose domain has more than one value;
  label(vars)              -- generator of solutions {v: value}, by search.
linear() and relation() propagate at once and return what fix() returns.

Propagation. A constraint is revised when posted and whenever a domain of
one of its variables shrinks; revisions are queued first in, first out, a
constraint at most once in the queue, until none is queued: the fixpoint.
A linear constraint removes each value outside the bounds the other terms
allow (bounds consistency, exact integer arithmetic). A relation keeps the
values that appear in some tuple of the current domains satisfying pred
(arc consistency; its cost is the product of its domains' sizes). A domain
that becomes empty is failure: fix() returns False, with the queue cleared
and the domains as they were at the failure (undo them with the trail).
At the fixpoint, residual() is what remains to decide; each constraint
prints as its relation (repr).

With a trail (a list), every narrowing and every post appends its undo, so
that search.undo restores the store; label() requires one. label(vars)
picks the first variable of vars with more than one value, tries its values
in increasing order (each by fix), and yields when every variable of vars
has one value.
"""
from .search import search


class Fail(Exception):
    pass


class Linear:
    def __init__(self, terms, op, c):
        self.terms, self.op, self.c = list(terms), op, c
        self.vars = [v for _, v in self.terms]

    def revise(self, s):
        if not all(s.dom[v] for v in self.vars):
            raise Fail(self)
        sign = -1 if self.op == ">=" else 1
        terms, c = [(sign * a, v) for a, v in self.terms], sign * self.c
        lo = [min(a * x for x in s.dom[v]) for a, v in terms]
        hi = [max(a * x for x in s.dom[v]) for a, v in terms]
        for i, (a, v) in enumerate(terms):
            top = c - (sum(lo) - lo[i])
            bot = c - (sum(hi) - hi[i]) if self.op == "==" else None
            s.narrow(v, lambda x: a * x <= top and (bot is None or a * x >= bot))

    def __repr__(self):
        return "%s %s %r" % (" + ".join("%r*%r" % t for t in self.terms), self.op, self.c)


class Relation:
    def __init__(self, vars, pred):
        self.vars, self.pred = list(vars), pred

    def revise(self, s):
        tuples = [()]
        for v in self.vars:
            tuples = [t + (x,) for t in tuples for x in s.dom[v]]
        ok = [t for t in tuples if self.pred(*t)]
        for i, v in enumerate(self.vars):
            s.narrow(v, {t[i] for t in ok}.__contains__)

    def __repr__(self):
        return "%s%r" % (getattr(self.pred, "__name__", "relation"), tuple(self.vars))


class Store:
    def __init__(self, trail=None):
        self.dom, self.watch, self.cons = {}, {}, []
        self.queue, self.queued, self.trail = [], set(), trail

    def var(self, v, values):
        self.dom[v] = set(values)
        self.watch.setdefault(v, [])

    def narrow(self, v, keep):
        old = self.dom[v]
        new = {x for x in old if keep(x)}
        if len(new) == len(old):
            return
        self.dom[v] = new
        if self.trail is not None:
            self.trail.append(lambda: self.dom.__setitem__(v, old))
        if not new:
            raise Fail(v)
        for c in self.watch[v]:
            if c not in self.queued:
                self.queued.add(c)
                self.queue.append(c)

    def fix(self, v=None, keep=None):
        try:
            if v is not None:
                self.narrow(v, keep)
            while self.queue:
                c = self.queue.pop(0)
                self.queued.discard(c)
                c.revise(self)
            return True
        except Fail:
            self.queue.clear()
            self.queued.clear()
            return False

    def post(self, c):
        self.cons.append(c)
        for v in c.vars:
            self.watch[v].append(c)
        if self.trail is not None:
            self.trail.append(lambda: [self.cons.pop()] + [self.watch[v].pop() for v in c.vars])
        self.queued.add(c)
        self.queue.append(c)
        return self.fix()

    def linear(self, terms, op, c):
        return self.post(Linear(terms, op, c))

    def relation(self, vars, pred):
        return self.post(Relation(vars, pred))

    def value(self, v):
        d = self.dom[v]
        return next(iter(d)) if len(d) == 1 else None

    def residual(self):
        return [c for c in self.cons if any(len(self.dom[v]) > 1 for v in c.vars)]

    def label(self, vars):
        def children(store):
            v = next(v for v in vars if len(self.dom[v]) != 1)
            for x in sorted(self.dom[v]):
                if self.fix(v, x.__eq__):
                    yield store

        def done(store):
            return all(len(self.dom[v]) == 1 for v in vars)

        assert self.trail is not None, "label() needs a Store with a trail"
        if self.fix():
            for _ in search(self, children, done, self.trail):
                yield {v: self.value(v) for v in vars}

#!/usr/bin/env python3
"""Syntax and static check of a Python program for the study. It never runs
the program: it reads its bytes, compiles them with compile() (which
executes nothing) and walks the syntax tree (ast.parse). See
harnesses/python/README.md, "check".

    harnesses/python/check CONFIGURATION PROGRAM

Exit status: 0 no error found; 1 errors found (listed); 2 usage error.
"""

import ast
import os
import sys
import warnings

CONFIGURATIONS = ("core", "stdlib-concurrency", "extended")
CONCURRENCY = {"threading", "queue", "asyncio"}
sys.dont_write_bytecode = True
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import constants as cpconst  # noqa: E402  (harnesses/python/constants.py)

H_NAMES = {"stage", "answer", "emit", "bindings", "pending", "suspended", "held",
           "problem_alternatives", "relations", "computation", "params"}
STAGE_ATTRS = {"k", "replay", "commitment", "params", "constants"}


def main(argv):
    if len(argv) != 3 or argv[1] not in CONFIGURATIONS:
        sys.stderr.write("usage: check CONFIGURATION PROGRAM   (CONFIGURATION: %s)\n" % ", ".join(CONFIGURATIONS))
        return 2
    config, path = argv[1], argv[2]
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError as e:
        sys.stderr.write("check: cannot read %s: %s\n" % (path, e))
        return 2
    errors, notes = [], []

    # 1. compile: syntax errors and compile-time warnings, verbatim
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        try:
            compile(data, path, "exec", dont_inherit=True)
        except SyntaxError as e:
            import traceback
            errors.append("".join(traceback.format_exception_only(type(e), e)).rstrip("\n"))
        except ValueError as e:      # null bytes, for instance
            errors.append("ValueError: %s" % e)
    for w in caught:
        notes.append(warnings.formatwarning(w.message, w.category, w.filename, w.lineno).rstrip("\n"))
    if errors:
        report(path, config, errors, notes)
        return 1

    text = data.decode("utf-8", errors="replace")
    lines = text.splitlines()
    tree = ast.parse(data, path)

    # 2. the harness declarations README.md requires
    posing = [l for l in lines if l.lstrip().startswith("#") and "CP-POSING:" in l]
    if len(posing) != 1:
        errors.append("the program must have exactly one line '# CP-POSING: incremental' or '# CP-POSING: reposed' (found %d)" % len(posing))
    else:
        val = posing[0].split("CP-POSING:", 1)[1].strip()
        if val not in ("incremental", "reposed"):
            errors.append("CP-POSING must be 'incremental' or 'reposed', not %r" % val)
        else:
            notes.append("posing: %s" % val)

    # 3. the constants block: parsed here exactly as run parses it, never executed
    where, consts, cerrs = cpconst.parse(text)
    errors += cerrs
    if where is None and not cerrs:
        notes.append("no constants block: the record will say constants.how = 'none' (right only for a sub-problem without constants)")
    elif where is not None and not cerrs:
        notes.append("constants block: lines %d-%d; delivered with their stages: %s" % (
            where[0] + 1, where[1] + 1,
            "; ".join("stage %d: %s" % (k, ", ".join(sorted(v))) for k, v in sorted(consts.items())) or "nothing"))
    if where is not None and not isinstance(where, str):
        b, e = where[0] + 1, where[1] + 1
        names = {nm for v in consts.values() for nm in v}
        for n in ast.walk(tree):
            if isinstance(n, ast.Name) and n.id in names and not (b < n.lineno < e):
                errors.append("line %d: %s is a constant of the block, which the program never executes: read it from s.constants[%r] when its stage is posed" % (n.lineno, n.id, n.id))

    # 4. imports, by configuration (systems/python/README.md)
    for n in ast.walk(tree):
        if isinstance(n, (ast.Import, ast.ImportFrom)):
            mods = [a.name for a in n.names] if isinstance(n, ast.Import) else [n.module or "." * n.level]
            for m in mods:
                top = m.split(".")[0]
                if top == "S":
                    if config == "extended":
                        notes.append("line %d: imports %s: an S mechanism of extended (S-mechanisms.md), counted once per mechanism" % (n.lineno, m))
                    else:
                        errors.append("line %d: imports %s, an S mechanism, which only the extended configuration adds" % (n.lineno, m))
                elif top in CONCURRENCY:
                    if config == "stdlib-concurrency":
                        notes.append("line %d: imports %s (a mechanism of stdlib-concurrency)" % (n.lineno, m))
                    else:
                        errors.append("line %d: imports %s, which only the stdlib-concurrency configuration adds" % (n.lineno, m))
                else:
                    notes.append("line %d: imports %s: an external mechanism, to be listed (systems/python/README.md)" % (n.lineno, m))

    # 5. no reading of the program's own text, where every stage's constants are
    for n in ast.walk(tree):
        if isinstance(n, ast.Name) and n.id in ("__file__", "open", "__loader__", "__spec__"):
            errors.append("line %d: %s: a program may not read files (its own text holds every stage's constants)" % (n.lineno, n.id))
        if isinstance(n, (ast.Import, ast.ImportFrom)):
            mods = [x.name for x in n.names] if isinstance(n, ast.Import) else [n.module or ""]
            for m in mods:
                if m.split(".")[0] in ("linecache", "inspect", "tokenize", "pathlib", "io", "runpy", "importlib"):
                    errors.append("line %d: imports %s, which reads source or files (a program's own text holds every stage's constants)" % (n.lineno, m))

    # 6. the H calls: names on cp, attributes of a stage
    for n in ast.walk(tree):
        if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name) and n.value.id == "cp":
            if n.attr not in H_NAMES:
                errors.append("line %d: cp.%s is not a harness call (README.md: %s)" % (n.lineno, n.attr, ", ".join(sorted(H_NAMES))))
    uses_stage = any(isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name) and n.value.id == "cp" and n.attr == "stage"
                     for n in ast.walk(tree))
    if not uses_stage:
        errors.append("the program never calls cp.stage(): it cannot receive a stage")
    report(path, config, errors, notes)
    return 1 if errors else 0


def report(path, config, errors, notes):
    print("check %s %s: %s" % (config, path, "%d error(s)" % len(errors) if errors else "no errors found"))
    for e in errors:
        print("error: " + e.replace("\n", "\n       "))
    for n in notes:
        print("note: " + n)
    print("(nothing was executed: the program was compiled and its syntax tree read)")


if __name__ == "__main__":
    sys.exit(main(sys.argv))
"""The marked constants block of a Python program (README.md, section 3.1):
found, checked and parsed by the harness, never executed by the program.

    # CONSTANTS BEGIN
    # stage 1
    NAME = <literal>
    # stage 3
    OTHER = <literal>
    # CONSTANTS END

Used by `run` (which delivers stage k's entries with stage k) and `check`.
Neither imports nor executes the program.
"""
import ast
import re

STAGE_RE = re.compile(r"^\s*#\s*stage\s+(\d+)\s*$")


def find(lines):
    """(begin, end) 0-based indexes of the marker lines, None if there is no
    block, or a string saying what is wrong."""
    begins = [i for i, l in enumerate(lines) if l.lstrip().startswith("#") and "CONSTANTS BEGIN" in l]
    ends = [i for i, l in enumerate(lines) if l.lstrip().startswith("#") and "CONSTANTS END" in l]
    if not begins and not ends:
        return None
    if len(begins) != 1 or len(ends) != 1 or ends[0] < begins[0]:
        return "there must be one '# CONSTANTS BEGIN' line followed by one '# CONSTANTS END' line (found %d and %d)" % (len(begins), len(ends))
    return begins[0], ends[0]


def parse(text):
    """Returns (block, constants, errors). block is (begin, end) or None;
    constants is {stage: {name: value}}; errors lists what is wrong."""
    lines = text.splitlines()
    where = find(lines)
    if where is None:
        return None, {}, []
    if isinstance(where, str):
        return None, {}, [where]
    b, e = where
    body = lines[b + 1:e]
    errors = []
    try:
        tree = ast.parse("\n".join(body))
    except SyntaxError as x:
        return where, {}, ["line %d: the constants block does not parse: %s" % (b + 1 + (x.lineno or 0), x.msg)]
    headers = [(i + 1, int(m.group(1))) for i, l in enumerate(body) for m in [STAGE_RE.match(l)] if m]
    consts = {}
    for n in tree.body:
        line = b + 1 + n.lineno     # 1-based line number in the program
        stage = None
        for hl, k in headers:
            if hl < n.lineno:
                stage = k
        if not isinstance(n, ast.Assign) or len(n.targets) != 1 or not isinstance(n.targets[0], ast.Name):
            errors.append("line %d: the constants block may hold only assignments of one literal value to one name" % line)
            continue
        try:
            value = ast.literal_eval(n.value)
        except (ValueError, TypeError, SyntaxError, MemoryError, RecursionError):
            errors.append("line %d: the value assigned to %s is not a literal" % (line, n.targets[0].id))
            continue
        if stage is None:
            errors.append("line %d: %s comes before any '# stage k' line: every constant is tagged with the stage that first uses it" % (line, n.targets[0].id))
            continue
        if stage < 1:
            errors.append("line %d: stage %d: stages are numbered from 1" % (line, stage))
            continue
        name = n.targets[0].id
        if name in consts.get(stage, {}):
            errors.append("line %d: %s is given twice for stage %d" % (line, name, stage))
            continue
        consts.setdefault(stage, {})[name] = value
    return where, consts, errors


def blanked(text, where):
    """The program's text with the block's lines between the markers made
    empty, so that line numbers are kept and nothing in the block runs."""
    if where is None:
        return text
    lines = text.split("\n")
    b, e = where
    for i in range(b + 1, e):
        lines[i] = ""
    return "\n".join(lines)

